            if ox-4<x<ox+0.5:
                if y>oy: L.append(y-oy)
                else: R.append(oy-y)
        gl=min(L) if L else 3
        gr=min(R) if R else 3
        tg=max(-12,min(12,3*(gr-gl)))
    s=max(-34,min(34,2.5*(h-tg)))
    return (s,-0.6,-23)

